func (s *Service) verifiedWatchChild(ctx context.Context, db *store.DB, home string, project store.Project, flags map[string]string) (bool, error) {
	projectID, projectErr := strconv.ParseInt(flags["watch-project-id"], 10, 64)
	watchPID, pidErr := strconv.Atoi(flags["watch-pid"])
	startedAt, startedErr := strconv.ParseInt(flags["watch-started-at"], 10, 64)
	token := flags["watch-token"]
	if projectErr != nil || pidErr != nil || startedErr != nil || projectID != project.ID || watchPID < 2 || startedAt < 1 || token == "" ||
		os.Getenv(watchRuntimeProjectEnv) != strconv.FormatInt(projectID, 10) || os.Getenv(watchRuntimeTokenEnv) != token || os.Getenv(watchRuntimeStartedEnv) != strconv.FormatInt(startedAt, 10) {
		return false, nil
	}
	watch, err := db.WatchRuntime(ctx, project.ID)
	if err != nil {
		return false, err
	}
	ancestors := processAncestors(procRoot, os.Getpid())
	if !watchChildIdentityMatches(project.ID, flags, parseProcessEnvironment(strings.Join(os.Environ(), "\x00")), watch, ancestors) || !watchRuntimeProcessHealthy(home, project.ID, watch) {
		return false, nil
	}
	for _, parent := range ancestors {
		if parent.pid != watchPID {
			continue
		}
		process, ok := inspectWatchProcess(home, watchPID)
		if !ok || !process.PollOnly || !watchProcessMatchesWatch(process, project.ID, watch) ||
			process.Executable.Device != watch.ExecutableDevice || process.Executable.Inode != watch.ExecutableInode ||
			!samePath(parent.cwd, project.Root) || !samePath(process.WorkingDir, project.Root) {
			return false, nil
		}
		cwd, err := currentDir()
		if err != nil {
			return false, err
		}
		return samePath(cwd, project.Root), nil
	}
	return false, nil
}

func watchChildIdentityMatches(projectID int64, flags, environment map[string]string, watch store.WatchRuntime, ancestors []ancestorProcess) bool {
	flagProject, projectErr := strconv.ParseInt(flags["watch-project-id"], 10, 64)
	flagPID, pidErr := strconv.Atoi(flags["watch-pid"])
	startedAt, startedErr := strconv.ParseInt(flags["watch-started-at"], 10, 64)
	if projectErr != nil || pidErr != nil || startedErr != nil || flagProject != projectID || flagPID != watch.PID ||
		flags["watch-token"] == "" || flags["watch-token"] != watch.Token || startedAt != watch.StartedAt ||
		environment[watchRuntimeProjectEnv] != strconv.FormatInt(projectID, 10) || environment[watchRuntimeTokenEnv] != watch.Token ||
		environment[watchRuntimeStartedEnv] != strconv.FormatInt(watch.StartedAt, 10) {
		return false
	}
	for _, parent := range ancestors {
		if parent.pid == watch.PID {
			return true
		}
	}
	return false
}

func (s *Service) runProjectWatchRuntime(ctx *axi.Context, db *store.DB, project store.Project, timeout time.Duration, stopSignals <-chan os.Signal) error {
	token := os.Getenv(watchRuntimeTokenEnv)
	if token == "" {
		return s.runWatchLoop(ctx, db, project, timeout, stopSignals, nil)
	}
	projectID, err := strconv.ParseInt(os.Getenv(watchRuntimeProjectEnv), 10, 64)
	if err != nil || projectID != project.ID {
		return axi.Failure("watch_project_mismatch", "hidden Watch identity does not match this Project", false)
	}
	startedAt, err := strconv.ParseInt(os.Getenv(watchRuntimeStartedEnv), 10, 64)
	if err != nil || startedAt < 1 {
		return axi.Failure("watch_identity_invalid", "hidden Watch start identity is invalid", false)
	}
	binary, err := os.Executable()
	if err != nil {
		return err
	}
	identity, ok := watchExecutableAt(binary)
	if !ok {
		return fmt.Errorf("cannot identify hidden Watch executable %q", binary)
	}
	home, err := s.homePath()
	if err != nil {
		return err
	}
	log, err := openWatchRuntimeLog(watchRuntimeLogPath(home, project))
	if err != nil {
		return fmt.Errorf("open Project Watch log: %w", err)
	}
	defer log.Close()
	stamped := &timestampedLines{out: log}
	ctx.Out, ctx.ErrOut = stamped, stamped
	watch := store.WatchRuntime{PID: os.Getpid(), Token: token, StartedAt: startedAt, HeartbeatAt: currentTime(), ExecutablePath: identity.Path, ExecutableDevice: identity.Device, ExecutableInode: identity.Inode, ExecutableSize: identity.Size, ExecutableModifiedAt: identity.ModifiedAt, ExecutableVersion: watchExecutableVersion(identity.Path)}
	if err := db.SetWatchRuntime(ctx.Context, project.ID, watch); err != nil {
		return err
	}
	defer db.ClearWatchRuntime(context.Background(), project.ID, os.Getpid(), token)
	return s.runWatchLoop(ctx, db, project, timeout, stopSignals, &watch)
}

func stopParkedWatchSystemd(ctx *axi.Context, home string, project store.Project, watch *store.WatchRuntime) {
	if watch == nil || !systemdWatchUnitLoaded(ctx.Context, home, project.ID) {
		return
	}
	if err := stopSystemdWatchNoBlock(ctx.Context, home, project.ID); err != nil {
		fmt.Fprintf(ctx.ErrOut, "Stop parked Project Watch for %s: %v\n", project.Name, err)
	}
}

func (s *Service) runWatchLoop(ctx *axi.Context, db *store.DB, project store.Project, timeout time.Duration, stopSignals <-chan os.Signal, watch *store.WatchRuntime) error {
	loopCtx := ctx.Context
	if watch != nil {
		stopHeartbeat := startWatchRuntimeHeartbeat(loopCtx, db, project.ID, *watch, func(err error) {
			fmt.Fprintf(ctx.ErrOut, "Watch progress heartbeat failed for %s: %v\n", project.Name, err)
